def weigh_in_skips(apps, schema_editor):
    """Weigh-ins already "Skip today"-ed get the Planner's skipped status (shown with the skip mark)."""
    Log = apps.get_model("albright_fitness", "WeighInLog")
    Completion = apps.get_model("albright_planner", "ItemCompletion")
    for log in Log.objects.filter(skipped=True).only("item_id", "occurrence_date"):
        Completion.objects.filter(item_id=log.item_id, occurrence_date=log.occurrence_date).update(status="skipped")


